(32, 4, '电商运营管培生', '运营', '杭州', '电商', 10000, 16000, '本科', '应届', 1, '1. 参与电商平台店铺运营全流程；\n2. 协助策划促销活动与内容营销；\n3. 分析销售数据并提出优化建议。', '1. 本科及以上学历，市场营销/电子商务相关专业；\n2. 对电商行业有热情，学习能力强；\n3. 有电商实习经验者优先。', '五险一金,带薪年假,弹性工时,节日福利,团建活动', 5, 1, 1, '2026-09-16 22:53:51', NULL, '2026-09-16 22:53:51', 158, 15, '2026-09-16 22:53:00', '2026-09-16 22:53:00', 0),
(33, 4, '供应链管理专员', '供应链', '杭州', '电商', 12000, 20000, '本科', '应届/1年', 1, '1. 负责供应商管理与采购协调；\n2. 跟进库存周转与物流效率；\n3. 参与供应链数字化优化项目。', '1. 本科及以上学历，物流/供应链管理相关专业；\n2. 数据分析能力强，熟练使用 Excel/SQL；\n3. 有供应链实习经验者优先。', '五险一金,带薪年假,弹性工时,节日福利,团建活动', 2, 1, 1, '2026-09-16 22:53:51', NULL, '2026-09-16 22:53:51', 231, 26, '2026-09-16 22:53:00', '2026-09-16 22:53:00', 0),
(34, 1, '大数据开发工程师', '大数据', '杭州', '互联网', 22000, 38000, '本科', '1-3年', 1, '1. 负责大数据平台开发与维护；\n2. 优化数据 pipeline 性能；\n3. 参与数据治理与质量保障。', '1. 本科及以上学历，计算机相关专业；\n2. 熟悉 Hadoop/Spark/Flink，了解 SQL；\n3. 有大数据项目经验者优先。', '五险一金,带薪年假,年终奖金,员工旅游,培训机会', 4, 1, 1, '2026-09-16 22:53:51', NULL, '2026-09-16 22:53:51', 239, 48, '2026-09-16 22:53:00', '2026-09-16 22:53:00', 0),
(35, 1, '云原生架构师', '架构', '杭州', '互联网', 30000, 50000, '本科', '3-5年', 1, '1. 负责云原生技术架构设计与落地；\n2. 推进容器化与微服务治理；\n3. 主导技术选型与性能优化。', '1. 本科及以上学历，计算机相关专业；\n2. 精通 Kubernetes/Docker，熟悉 Service Mesh；\n3. 有大规模分布式系统架构经验。', '五险一金,带薪年假,年终奖金,员工旅游,培训机会', 2, 1, 1, '2026-09-16 22:53:51', NULL, '2026-09-16 22:53:51', 356, 11, '2026-09-16 22:53:00', '2026-09-16 22:53:00', 0),
