(37, 2, '安全研究员', '信息安全', '深圳', '互联网', 25000, 40000, '硕士', '1-3年', 1, '1. 负责安全漏洞挖掘与分析；\n2. 开发安全检测工具与平台；\n3. 参与安全应急响应。', '1. 硕士及以上学历，信息安全/计算机相关专业；\n2. 熟悉 Web 安全/二进制安全，有 CTF 经验者优先；\n3. 责任心强，善于学习。', '五险一金,带薪年假,年终奖金,员工旅游,培训机会', 2, 1, 1, '2026-09-16 22:53:51', NULL, '2026-09-16 22:53:51', 216, 21, '2026-09-16 22:53:00', '2026-09-16 22:53:00', 0),
(38, 3, '推荐系统工程师', '推荐系统', '北京', '互联网', 25000, 45000, '本科', '1-3年', 1, '1. 负责推荐系统核心算法研发；\n2. 优化推荐效果与用户留存；\n3. 参与大规模特征工程与模型训练。', '1. 本科及以上学历，计算机/数学相关专业；\n2. 熟悉推荐系统常用算法，了解 TensorFlow/PyTorch；\n3. 有推荐系统项目经验者优先。', '五险一金,带薪年假,年终奖金,员工旅游,培训机会', 3, 1, 1, '2026-09-16 22:53:51', NULL, '2026-09-16 22:53:51', 325, 10, '2026-09-16 22:53:00', '2026-09-16 22:53:00', 0),
